-- Add extended profile fields to the profiles table
-- All columns are nullable; existing rows are unaffected

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS username text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS bio text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS avatar_url text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS job_title text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS company text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS location text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS website text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS twitter text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS linkedin text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS github text;

import { useState, useEffect, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import SidebarLayout from "@/components/SidebarLayout";
import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Upload,
  X,
  Globe,
  Twitter,
  Linkedin,
  Github,
  Briefcase,
  MapPin,
  Crown,
  Zap,
  FileText,
  Loader2,
} from "lucide-react";

// ─── helpers ────────────────────────────────────────────────────────────────

function getInitials(email?: string | null, fullName?: string | null): string {
  if (fullName) {
    const parts = fullName.trim().split(/\s+/);
    if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
    return parts[0][0]?.toUpperCase() ?? "?";
  }
  if (!email) return "?";
  const local = email.split("@")[0];
  const parts = local.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return local[0]?.toUpperCase() ?? "?";
}

// ─── types ───────────────────────────────────────────────────────────────────

interface ExtendedProfile {
  full_name: string | null;
  username: string | null;
  bio: string | null;
  avatar_url: string | null;
  job_title: string | null;
  company: string | null;
  location: string | null;
  website: string | null;
  twitter: string | null;
  linkedin: string | null;
  github: string | null;
}

interface FormState {
  full_name: string;
  username: string;
  bio: string;
  avatar_url: string;
  job_title: string;
  company: string;
  location: string;
  website: string;
  twitter: string;
  linkedin: string;
  github: string;
}

const EMPTY_FORM: FormState = {
  full_name: "",
  username: "",
  bio: "",
  avatar_url: "",
  job_title: "",
  company: "",
  location: "",
  website: "",
  twitter: "",
  linkedin: "",
  github: "",
};

function profileToForm(p: ExtendedProfile): FormState {
  return {
    full_name: p.full_name ?? "",
    username: p.username ?? "",
    bio: p.bio ?? "",
    avatar_url: p.avatar_url ?? "",
    job_title: p.job_title ?? "",
    company: p.company ?? "",
    location: p.location ?? "",
    website: p.website ?? "",
    twitter: p.twitter ?? "",
    linkedin: p.linkedin ?? "",
    github: p.github ?? "",
  };
}

// ─── component ───────────────────────────────────────────────────────────────

const Profile = () => {
  const { user, profile, refreshProfile } = useAuth();
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [saving, setSaving] = useState(false);
  const [avatarUploading, setAvatarUploading] = useState(false);

  const plan = profile?.plan ?? "free";
  const isPaid = plan !== "free";
  const sub = profile?.subscription_credits ?? 0;
  const top = profile?.topup_credits ?? 0;
  const bonus = profile?.bonus_credits ?? 0;
  const split = sub + top + bonus;
  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);

  // ── load extended profile (React Query, independent of useAuth) ──────────
  const { data: fullProfile, isLoading: profileLoading } = useQuery<ExtendedProfile>({
    queryKey: ["profileFull", user?.id],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("profiles")
        .select("full_name, username, bio, avatar_url, job_title, company, location, website, twitter, linkedin, github")
        .eq("user_id", user!.id)
        .single();
      if (error) throw error;
      return data as ExtendedProfile;
    },
    enabled: !!user,
    staleTime: 5 * 60 * 1000,
  });

  // ── load usage stats ─────────────────────────────────────────────────────
  const { data: stats } = useQuery({
    queryKey: ["profileStats", user?.id],
    queryFn: async () => {
      const [jobsRes, usageRes] = await Promise.all([
        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user!.id),
        supabase.from("usage_logs").select("credits_used").eq("user_id", user!.id),
      ]);
      const jobs = jobsRes.data ?? [];
      const totalJobs = jobs.length;
      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
      const creditsUsed = (usageRes.data ?? []).reduce(
        (sum: number, u: any) => sum + (u.credits_used ?? 0),
        0,
      );
      return { totalJobs, totalResumes, creditsUsed };
    },
    enabled: !!user,
    staleTime: 5 * 60 * 1000,
  });

  // ── populate form when profile loads ────────────────────────────────────
  useEffect(() => {
    if (fullProfile) {
      setForm(profileToForm(fullProfile));
    }
  }, [fullProfile]);

  const set = (key: keyof FormState) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
    setForm((f) => ({ ...f, [key]: e.target.value }));

  // ── avatar upload ────────────────────────────────────────────────────────
  const handleAvatarFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;

    const maxMB = 5;
    if (file.size > maxMB * 1024 * 1024) {
      toast.error(`Image must be under ${maxMB}MB`);
      return;
    }
    if (!file.type.startsWith("image/")) {
      toast.error("Only image files are supported");
      return;
    }

    setAvatarUploading(true);
    try {
      const ext = file.name.split(".").pop();
      const path = `${user.id}/avatar.${ext}`;

      const { error: uploadError } = await supabase.storage
        .from("avatars")
        .upload(path, file, { upsert: true, contentType: file.type });

      if (uploadError) throw uploadError;

      const { data: urlData } = supabase.storage.from("avatars").getPublicUrl(path);
      const publicUrl = urlData.publicUrl + `?t=${Date.now()}`;

      // Save immediately to profiles
      await (supabase as any)
        .from("profiles")
        .update({ avatar_url: publicUrl })
        .eq("user_id", user.id);

      setForm((f) => ({ ...f, avatar_url: publicUrl }));
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
      toast.success("Avatar updated");
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Upload failed";
      toast.error(msg);
    } finally {
      setAvatarUploading(false);
      // Reset file input so the same file can be re-selected
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const handleRemoveAvatar = async () => {
    if (!user) return;
    // Best-effort storage delete — do not block on failure
    try {
      await supabase.storage.from("avatars").remove([`${user.id}/avatar.jpg`, `${user.id}/avatar.png`, `${user.id}/avatar.webp`]);
    } catch {
      // ignore
    }
    setForm((f) => ({ ...f, avatar_url: "" }));
    try {
      await (supabase as any)
        .from("profiles")
        .update({ avatar_url: null })
        .eq("user_id", user.id);
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
      toast.success("Avatar removed");
    } catch {
      toast.error("Failed to remove avatar");
    }
  };

  // ── save ─────────────────────────────────────────────────────────────────
  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("profiles")
        .update({
          full_name: form.full_name || null,
          username: form.username || null,
          bio: form.bio || null,
          avatar_url: form.avatar_url || null,
          job_title: form.job_title || null,
          company: form.company || null,
          location: form.location || null,
          website: form.website || null,
          twitter: form.twitter || null,
          linkedin: form.linkedin || null,
          github: form.github || null,
        })
        .eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
      toast.success("Profile updated");
    } catch {
      toast.error("Failed to save profile");
    } finally {
      setSaving(false);
    }
  };

  // ── cancel — reset to last loaded values ─────────────────────────────────
  const handleCancel = () => {
    if (fullProfile) setForm(profileToForm(fullProfile));
    else setForm(EMPTY_FORM);
  };

  // ── member since ─────────────────────────────────────────────────────────
  const memberSince = user?.created_at
    ? new Date(user.created_at).toLocaleDateString("en-US", { month: "long", year: "numeric" })
    : "—";

  // ─── render ───────────────────────────────────────────────────────────────
  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        {/* Page header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-foreground">Profile</h1>
          <p className="text-sm text-muted-foreground mt-1">Manage your personal information and preferences</p>
        </div>

        <div className="space-y-6">
          {/* ── Main profile card ──────────────────────────────────────── */}
          <Card className="border border-border/60 shadow-sm">
            <CardContent className="p-6 space-y-0">

              {/* Avatar section */}
              <div className="flex items-center gap-5">
                {/* Circle */}
                <div className="relative shrink-0">
                  {profileLoading ? (
                    <Skeleton className="h-20 w-20 rounded-full" />
                  ) : form.avatar_url ? (
                    <img
                      src={form.avatar_url}
                      alt="Avatar"
                      className="h-20 w-20 rounded-full object-cover ring-2 ring-border"
                    />
                  ) : (
                    <div className="h-20 w-20 rounded-full bg-primary/10 text-primary text-xl font-bold flex items-center justify-center ring-2 ring-border select-none">
                      {getInitials(user?.email, form.full_name)}
                    </div>
                  )}
                </div>

                {/* Upload/remove controls */}
                <div className="flex flex-col gap-2">
                  <div className="flex items-center gap-2 flex-wrap">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => fileInputRef.current?.click()}
                      disabled={avatarUploading}
                      className="h-8 gap-1.5 text-xs"
                    >
                      {avatarUploading ? (
                        <Loader2 className="h-3 w-3 animate-spin" />
                      ) : (
                        <Upload className="h-3 w-3" />
                      )}
                      {avatarUploading ? "Uploading…" : "Upload photo"}
                    </Button>
                    {form.avatar_url && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={handleRemoveAvatar}
                        className="h-8 gap-1.5 text-xs text-muted-foreground hover:text-destructive"
                      >
                        <X className="h-3 w-3" />
                        Remove
                      </Button>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground">JPG, PNG or WebP. Max 5 MB.</p>
                </div>

                {/* Hidden file input */}
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={handleAvatarFile}
                />
              </div>

              {/* ── Personal Information ──────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Personal Information
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Full name */}
                <div className="space-y-1.5">
                  <Label htmlFor="full-name" className="text-sm">Full Name</Label>
                  <Input
                    id="full-name"
                    placeholder="Jane Smith"
                    value={form.full_name}
                    onChange={set("full_name")}
                  />
                </div>

                {/* Username */}
                <div className="space-y-1.5">
                  <Label htmlFor="username" className="text-sm">Username</Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-sm text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      @
                    </span>
                    <input
                      id="username"
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="janesmith"
                      value={form.username}
                      onChange={(e) => setForm((f) => ({ ...f, username: e.target.value }))}
                    />
                  </div>
                </div>

                {/* Email — read-only */}
                <div className="space-y-1.5">
                  <Label htmlFor="email" className="text-sm">Email</Label>
                  <Input
                    id="email"
                    value={user?.email ?? ""}
                    disabled
                    className="cursor-not-allowed opacity-60"
                  />
                </div>

                {/* Member since — read-only display */}
                <div className="space-y-1.5">
                  <Label className="text-sm">Member Since</Label>
                  <div className="h-9 flex items-center px-3 rounded-md border border-input bg-muted/40 text-sm text-muted-foreground">
                    {memberSince}
                  </div>
                </div>

                {/* Bio — full width */}
                <div className="space-y-1.5 sm:col-span-2">
                  <Label htmlFor="bio" className="text-sm">Bio</Label>
                  <Textarea
                    id="bio"
                    placeholder="A short bio about yourself…"
                    value={form.bio}
                    onChange={set("bio")}
                    maxLength={160}
                    rows={3}
                    className="resize-none"
                  />
                  <p className="text-xs text-muted-foreground text-right tabular-nums">
                    {form.bio.length}/160
                  </p>
                </div>
              </div>

              {/* ── Work Details ──────────────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Work Details
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Job title */}
                <div className="space-y-1.5">
                  <Label htmlFor="job-title" className="text-sm flex items-center gap-1.5">
                    <Briefcase className="h-3.5 w-3.5 text-muted-foreground" />
                    Job Title
                  </Label>
                  <Input
                    id="job-title"
                    placeholder="Recruiting Manager"
                    value={form.job_title}
                    onChange={set("job_title")}
                  />
                </div>

                {/* Company */}
                <div className="space-y-1.5">
                  <Label htmlFor="company" className="text-sm">Company</Label>
                  <Input
                    id="company"
                    placeholder="Acme Corp"
                    value={form.company}
                    onChange={set("company")}
                  />
                </div>

                {/* Location — full width */}
                <div className="space-y-1.5 sm:col-span-2">
                  <Label htmlFor="location" className="text-sm flex items-center gap-1.5">
                    <MapPin className="h-3.5 w-3.5 text-muted-foreground" />
                    Location
                  </Label>
                  <Input
                    id="location"
                    placeholder="San Francisco, CA"
                    value={form.location}
                    onChange={set("location")}
                  />
                </div>
              </div>

              {/* ── Social Links ──────────────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Social Links
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Website */}
                <div className="space-y-1.5">
                  <Label className="text-sm flex items-center gap-1.5">
                    <Globe className="h-3.5 w-3.5 text-muted-foreground" />
                    Website
                  </Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      https://
                    </span>
                    <input
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="yoursite.com"
                      value={form.website}
                      onChange={(e) => setForm((f) => ({ ...f, website: e.target.value }))}
                    />
                  </div>
                </div>

                {/* Twitter */}
                <div className="space-y-1.5">
                  <Label className="text-sm flex items-center gap-1.5">
                    <Twitter className="h-3.5 w-3.5 text-muted-foreground" />
                    Twitter / X
