                    <Github className="h-3.5 w-3.5 text-muted-foreground" />
                    GitHub
                  </Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      github.com/
                    </span>
                    <input
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="yourname"
                      value={form.github}
                      onChange={(e) => setForm((f) => ({ ...f, github: e.target.value }))}
                    />
                  </div>
                </div>
              </div>

              {/* ── Plan & Usage ──────────────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Plan & Usage
              </p>

              {/* Plan badges */}
              <div className="flex flex-wrap items-center gap-2 mb-5">
                <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
                  {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
                  {isPaid ? plan : "Pay As You Go"}
                </Badge>
                <Badge variant="outline" className="gap-1.5 tabular-nums">
                  {totalCredits} credits
                </Badge>
                {profile?.subscription_ends_at && (
                  <span className="text-xs text-muted-foreground">
                    Subscription until{" "}
                    {new Date(profile.subscription_ends_at).toLocaleDateString("en-US", {
                      month: "short",
                      year: "numeric",
                    })}
                  </span>
                )}
              </div>

              {/* 3 stat cards */}
              <div className="grid grid-cols-3 gap-3">
                {!stats ? (
                  <>
                    {[0, 1, 2].map((i) => (
                      <div key={i} className="rounded-lg border border-border/60 p-4 space-y-1.5">
                        <Skeleton className="h-7 w-10" />
                        <Skeleton className="h-3 w-20" />
                      </div>
                    ))}
                  </>
                ) : (
                  <>
                    <div className="rounded-lg border border-border/60 bg-muted/30 p-4">
                      <div className="flex items-center gap-2">
                        <Briefcase className="h-4 w-4 text-muted-foreground shrink-0" />
                        <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalJobs}</span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">Jobs created</p>
                    </div>
                    <div className="rounded-lg border border-border/60 bg-muted/30 p-4">
                      <div className="flex items-center gap-2">
                        <FileText className="h-4 w-4 text-muted-foreground shrink-0" />
                        <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalResumes}</span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">Resumes ranked</p>
                    </div>
                    <div className="rounded-lg border border-border/60 bg-muted/30 p-4">
                      <div className="flex items-center gap-2">
                        <Zap className="h-4 w-4 text-muted-foreground shrink-0" />
                        <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.creditsUsed}</span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">Credits used</p>
                    </div>
                  </>
                )}
              </div>

              {/* ── Action buttons ────────────────────────────────────── */}
              <Separator className="my-6" />
              <div className="flex items-center justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleCancel}
                  disabled={saving}
                >
                  Cancel
                </Button>
                <Button
                  type="button"
                  onClick={handleSave}
                  disabled={saving}
                  className="gap-1.5"
                >
                  {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                  {saving ? "Saving…" : "Save Changes"}
                </Button>
              </div>

            </CardContent>
          </Card>

          {/* ── Change password card ───────────────────────────────────── */}
          <ChangePasswordCard />

        </div>
      </main>
    </SidebarLayout>
  );
};

export default Profile;
